"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[757],{780:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-04-linear-classification</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="лабораторная-работа-4-линейная-классификация-логистическая-регрессия-метрики-и-svm">Лабораторная\nработа 4. Линейная классификация: логистическая регрессия, метрики и\nSVM</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>Место в курсе</td>\n<td>после лекции 3</td>\n</tr>\n<tr>\n<td>Опора на лекции</td>\n<td>лекция 3: сигмоида (опр. 3.1), логистическая потеря (опр. 3.3),\nотступ (опр. 3.8), прямая и двойственная задачи SVM (опр. 3.9, теорема\n3.11), опорные векторы, мягкий зазор (опр. 3.14), ядра (опр. 3.17) и\nкритерий Мерсера</td>\n</tr>\n<tr>\n<td>Трудоёмкость</td>\n<td>2 ч аудиторно + домашняя работа (3–4 ч)</td>\n</tr>\n</tbody>\n</table>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Понять, чем логистическая регрессия и SVM отличаются друг от друга —\nи увидеть, что различие целиком заключено в виде функции потерь.\nНаучиться измерять качество классификации так, чтобы не обмануть себя:\nразобрать, когда accuracy бесполезна, а ROC-AUC оптимистична.</p>\n<h2 id="как-устроено-занятие">Как устроено занятие</h2>\n<p>Ноутбук разбирается в аудитории: код запускается и обсуждается по\nходу. Большая часть ячеек уже написана — их нужно <strong>прочитать и\nзапустить</strong>, разобравшись, что происходит и почему.</p>\n<p>Ячейки, помеченные <code># ✍ ЗАДАНИЕ НА СЕМИНАРЕ</code>, заполняются\nсамостоятельно прямо на занятии; их немного, и каждая занимает несколько\nстрок. Ячейки <strong>Вывод</strong> — тоже ваши: короткий ответ своими\nсловами на поставленный вопрос.</p>\n<p>Дома выполняется отдельный ноутбук <code>lab04_homework.ipynb</code>\n— там задания крупнее и делать их нужно самому.</p>\n<blockquote>\n<p><strong>Индивидуальный вариант.</strong> Датасет и набор методов\nвыдаются по вашему ФИО (см. ячейку ниже) — и на семинаре, и в домашней\nработе.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb1-45"><a href="#cb1-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-46"><a href="#cb1-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> make_blobs, make_circles, make_moons</span>\n<span id="cb1-47"><a href="#cb1-47" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> LogisticRegression</span>\n<span id="cb1-48"><a href="#cb1-48" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> train_test_split</span>\n<span id="cb1-49"><a href="#cb1-49" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> StandardScaler</span>\n<span id="cb1-50"><a href="#cb1-50" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.svm <span class="im">import</span> SVC</span>\n<span id="cb1-51"><a href="#cb1-51" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> labdata <span class="im">import</span> load_personal</span></code></pre></div>\n</div>\n<div id="cell002" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell003" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">4</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell004" class="cell markdown">\n<hr />\n<h1 id="часть-1-три-потери-как-функции-отступа">Часть 1. Три потери как\nфункции отступа</h1>\n<p>Определение 3.3 задаёт логистическую потерю при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi><mo>∈</mo><mo stretchy="false" form="prefix">{</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">y\\in\\{0,1\\}</annotation></semantics></math>.\nЕсли перейти к разметке\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi><mo>∈</mo><mo stretchy="false" form="prefix">{</mo><mi>−</mi><mn>1</mn><mo>,</mo><mi>+</mi><mn>1</mn><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">y\\in\\{-1,+1\\}</annotation></semantics></math>\nи ввести <strong>отступ</strong>\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mo>=</mo><mi>y</mi><mspace width="0.167em"></mspace><msup><mi>θ</mi><mi>𝖳</mi></msup><mi>x</mi></mrow><annotation encoding="application/x-tex">M = y\\,\\theta^{\\mathsf T}x</annotation></semantics></math>,\nто она записывается как\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi>ln</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>+</mo><msup><mi>e</mi><mrow><mi>−</mi><mi>M</mi></mrow></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\ln(1+e^{-M})</annotation></semantics></math>,\nи все три потери курса становятся сравнимы:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">[</mo><mi>M</mi><mo>&lt;</mo><mn>0</mn><mo stretchy="false" form="postfix">]</mo><mspace width="1.0em"></mspace><mtext mathvariant="normal">(пороговая)</mtext><mo>,</mo><mspace width="2.0em"></mspace><mrow><mi>ln</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>+</mo><msup><mi>e</mi><mrow><mi>−</mi><mi>M</mi></mrow></msup><mo stretchy="false" form="postfix">)</mo><mspace width="1.0em"></mspace><mtext mathvariant="normal">(логистическая)</mtext><mo>,</mo><mspace width="2.0em"></mspace><mrow><mi>max</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo>,</mo><mspace width="0.167em"></mspace><mn>1</mn><mo>−</mo><mi>M</mi><mo stretchy="false" form="postfix">)</mo><mspace width="1.0em"></mspace><mtext mathvariant="normal">(hinge, SVM)</mtext><mi>.</mi></mrow><annotation encoding="application/x-tex">\n[M&lt;0] \\quad\\text{(пороговая)},\\qquad\n\\ln(1+e^{-M}) \\quad\\text{(логистическая)},\\qquad\n\\max(0,\\,1-M) \\quad\\text{(hinge, SVM)}.\n</annotation></semantics></math></p>\n<p>Отступ — это «уверенность с учётом правильности»:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">M&gt;0</annotation></semantics></math>\nозначает верный ответ, и чем больше\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>M</mi><annotation encoding="application/x-tex">M</annotation></semantics></math>,\nтем дальше объект от границы.</p>\n</div>\n<div id="cell005" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> sigmoid(z):</span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Численно устойчивая сигмоида: без переполнения при больших |z|.</span></span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a><span class="co">    Наивная формула 1/(1+exp(-z)) при z = -1000 даёт exp(1000) = inf.</span></span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a><span class="co">    Приём: для z &gt;= 0 считать 1/(1+exp(-z)), для z &lt; 0 -- exp(z)/(1+exp(z)).</span></span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb3-9"><a href="#cb3-9" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co"> (4-5 строк)</span></span>\n<span id="cb3-10"><a href="#cb3-10" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb3-11"><a href="#cb3-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-12"><a href="#cb3-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-13"><a href="#cb3-13" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;sigmoid(-1000) =&quot;</span>, sigmoid(np.array([<span class="op">-</span><span class="fl">1000.0</span>]))[<span class="dv">0</span>], <span class="st">&quot;-- без переполнения&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell006" class="cell code">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a>M <span class="op">=</span> np.linspace(<span class="op">-</span><span class="dv">3</span>, <span class="dv">3</span>, <span class="dv">400</span>)</span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a>fig, ax <span class="op">=</span> plt.subplots()</span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a>ax.plot(M, (M <span class="op">&lt;</span> <span class="dv">0</span>).astype(<span class="bu">float</span>), lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="vs">r&quot;пороговая </span><span class="dv">$</span><span class="pp">[M&lt;0]</span><span class="dv">$</span><span class="vs">&quot;</span>)</span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a>ax.plot(M, np.log(<span class="dv">1</span> <span class="op">+</span> np.exp(<span class="op">-</span>M)), lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="vs">r&quot;логистическая </span><span class="dv">$</span><span class="er">\\</span><span class="vs">ln</span><span class="kw">(</span><span class="vs">1</span><span class="op">+</span><span class="vs">e</span><span class="dv">^</span><span class="vs">{-M}</span><span class="kw">)</span><span class="dv">$</span><span class="vs">&quot;</span>)</span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a>ax.plot(M, np.maximum(<span class="dv">0</span>, <span class="dv">1</span> <span class="op">-</span> M), lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="vs">r&quot;hinge </span><span class="dv">$\\m</span><span class="vs">ax</span><span class="kw">(</span><span class="vs">0,</span><span class="ch">\\,</span><span class="vs">1-M</span><span class="kw">)</span><span class="dv">$</span><span class="vs">&quot;</span>)</span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a>ax.set_xlabel(<span class="vs">r&quot;отступ </span><span class="dv">$</span><span class="vs">M = y</span><span class="ch">\\,\\t</span><span class="vs">heta</span><span class="dv">^</span><span class="vs">{</span><span class="dv">\\m</span><span class="vs">athsf{T}}x</span><span class="dv">$</span><span class="vs">&quot;</span>)<span class="op">;</span> ax.set_ylabel(<span class="st">&quot;потеря&quot;</span>)</span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a>ax.set_title(<span class="st">&quot;Потери как функции отступа&quot;</span>)<span class="op">;</span> ax.legend()</span>\n<span id="cb4-8"><a href="#cb4-8" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell007" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Почему пороговую потерю не минимизируют\nнапрямую? Какие два свойства логистической и hinge-потерь делают их\nпригодными?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell008" class="cell markdown">\n<hr />\n<h1 id="часть-2-разделимая-выборка-веса-уходят-в-бесконечность">Часть 2.\nРазделимая выборка: веса уходят в бесконечность</h1>\n<p>У логистической потери на линейно разделимой выборке <strong>нет\nминимума</strong>: для любого\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>θ</mi><annotation encoding="application/x-tex">\\theta</annotation></semantics></math>,\nразделяющего классы, увеличение\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mi>θ</mi><mo stretchy="false" form="postfix">∥</mo></mrow><annotation encoding="application/x-tex">\\|\\theta\\|</annotation></semantics></math>\nв\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>c</mi><annotation encoding="application/x-tex">c</annotation></semantics></math>\nраз увеличивает все отступы и уменьшает\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math>.\nФормально\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mrow><mi>inf</mi><mo>⁡</mo></mrow><mi>θ</mi></msub><mi>Q</mi><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\inf_\\theta Q = 0</annotation></semantics></math>,\nно инфимум не достигается.</p>\n</div>\n<div id="cell009" class="cell code">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a>X_sep <span class="op">=</span> rng.normal(size<span class="op">=</span>(<span class="dv">60</span>, <span class="dv">2</span>))</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a>y_sep <span class="op">=</span> (X_sep[:, <span class="dv">0</span>] <span class="op">+</span> X_sep[:, <span class="dv">1</span>] <span class="op">&gt;</span> <span class="dv">0</span>).astype(<span class="bu">int</span>)      <span class="co"># заведомо разделимо</span></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a>rows <span class="op">=</span> []</span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> C <span class="kw">in</span> [<span class="fl">0.01</span>, <span class="fl">1.0</span>, <span class="fl">100.0</span>, <span class="fl">10_000.0</span>]:</span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a>    m <span class="op">=</span> LogisticRegression(C<span class="op">=</span>C, max_iter<span class="op">=</span><span class="dv">100_000</span>).fit(X_sep, y_sep)</span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a>    p <span class="op">=</span> m.predict_proba(X_sep)[:, <span class="dv">1</span>]</span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a>    rows.append({<span class="st">&quot;C&quot;</span>: C, <span class="st">&quot;||theta||&quot;</span>: np.linalg.norm(m.coef_),</span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;мин. вероятность&quot;</span>: p.<span class="bu">min</span>(), <span class="st">&quot;макс. вероятность&quot;</span>: p.<span class="bu">max</span>(),</span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;ошибок&quot;</span>: <span class="bu">int</span>((m.predict(X_sep) <span class="op">!=</span> y_sep).<span class="bu">sum</span>())})</span>\n<span id="cb5-11"><a href="#cb5-11" aria-hidden="true" tabindex="-1"></a>display(pd.DataFrame(rows).set_index(<span class="st">&quot;C&quot;</span>).<span class="bu">round</span>(<span class="dv">4</span>))</span>\n<span id="cb5-12"><a href="#cb5-12" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;C -- обратный параметр регуляризации: чем больше C, тем слабее штраф&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell010" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Что происходит с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mi>θ</mi><mo stretchy="false" form="postfix">∥</mo></mrow><annotation encoding="application/x-tex">\\|\\theta\\|</annotation></semantics></math>\nи с вероятностями при росте\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>?\nПочему это плохо, даже если все ответы верны?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell011" class="cell markdown">\n<hr />\n<h1 id="часть-3-метрики-где-легко-обмануть-себя">Часть 3. Метрики: где\nлегко обмануть себя</h1>\n<p>Матрица ошибок при пороге\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>t</mi><annotation encoding="application/x-tex">t</annotation></semantics></math>\nдаёт четыре числа, из которых собираются все метрики:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext mathvariant="normal">precision</mtext><mo>=</mo><mfrac><mrow><mi>T</mi><mi>P</mi></mrow><mrow><mi>T</mi><mi>P</mi><mo>+</mo><mi>F</mi><mi>P</mi></mrow></mfrac><mo>,</mo><mspace width="1.0em"></mspace><mtext mathvariant="normal">recall</mtext><mo>=</mo><mi>T</mi><mi>P</mi><mi>R</mi><mo>=</mo><mfrac><mrow><mi>T</mi><mi>P</mi></mrow><mrow><mi>T</mi><mi>P</mi><mo>+</mo><mi>F</mi><mi>N</mi></mrow></mfrac><mo>,</mo><mspace width="1.0em"></mspace><mi>F</mi><mi>P</mi><mi>R</mi><mo>=</mo><mfrac><mrow><mi>F</mi><mi>P</mi></mrow><mrow><mi>F</mi><mi>P</mi><mo>+</mo><mi>T</mi><mi>N</mi></mrow></mfrac><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\text{precision} = \\frac{TP}{TP+FP},\\quad\n\\text{recall} = TPR = \\frac{TP}{TP+FN},\\quad\nFPR = \\frac{FP}{FP+TN}.\n</annotation></semantics></math></p>\n<p>ROC-кривая — точки\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">(</mo><mi>F</mi><mi>P</mi><mi>R</mi><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo stretchy="false" form="postfix">)</mo><mo>,</mo><mi>T</mi><mi>P</mi><mi>R</mi><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo stretchy="false" form="postfix">)</mo><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">(FPR(t), TPR(t))</annotation></semantics></math>\nпо всем порогам; PR-кривая —\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">(</mo><mtext mathvariant="normal">recall</mtext><mo>,</mo><mtext mathvariant="normal">precision</mtext><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">(\\text{recall}, \\text{precision})</annotation></semantics></math>.\nПосмотрим, что происходит с ними при росте дисбаланса классов.</p>\n</div>\n<div id="cell012" class="cell code">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> make_classification</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> accuracy_score, average_precision_score, roc_auc_score</span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> evaluate_at_balance(frac_pos, seed<span class="op">=</span>RANDOM_STATE):</span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Обучить логрег на выборке с заданной долей класса 1 и вернуть метрики.&quot;&quot;&quot;</span></span>\n<span id="cb6-7"><a href="#cb6-7" aria-hidden="true" tabindex="-1"></a>    X, y <span class="op">=</span> make_classification(n_samples<span class="op">=</span><span class="dv">4000</span>, n_features<span class="op">=</span><span class="dv">20</span>, n_informative<span class="op">=</span><span class="dv">5</span>,</span>\n<span id="cb6-8"><a href="#cb6-8" aria-hidden="true" tabindex="-1"></a>                              n_redundant<span class="op">=</span><span class="dv">3</span>, class_sep<span class="op">=</span><span class="fl">0.9</span>, flip_y<span class="op">=</span><span class="fl">0.02</span>,</span>\n<span id="cb6-9"><a href="#cb6-9" aria-hidden="true" tabindex="-1"></a>                              weights<span class="op">=</span>[<span class="dv">1</span> <span class="op">-</span> frac_pos, frac_pos], random_state<span class="op">=</span>seed)</span>\n<span id="cb6-10"><a href="#cb6-10" aria-hidden="true" tabindex="-1"></a>    Xa, Xv, ya, yv <span class="op">=</span> train_test_split(X, y, test_size<span class="op">=</span><span class="fl">0.3</span>, stratify<span class="op">=</span>y, random_state<span class="op">=</span>seed)</span>\n<span id="cb6-11"><a href="#cb6-11" aria-hidden="true" tabindex="-1"></a>    s <span class="op">=</span> StandardScaler().fit(Xa)</span>\n<span id="cb6-12"><a href="#cb6-12" aria-hidden="true" tabindex="-1"></a>    p <span class="op">=</span> LogisticRegression(max_iter<span class="op">=</span><span class="dv">5000</span>).fit(s.transform(Xa), ya).predict_proba(</span>\n<span id="cb6-13"><a href="#cb6-13" aria-hidden="true" tabindex="-1"></a>        s.transform(Xv))[:, <span class="dv">1</span>]</span>\n<span id="cb6-14"><a href="#cb6-14" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> {<span class="st">&quot;доля класса 1&quot;</span>: yv.mean(),</span>\n<span id="cb6-15"><a href="#cb6-15" aria-hidden="true" tabindex="-1"></a>            <span class="st">&quot;accuracy «всегда 0»&quot;</span>: accuracy_score(yv, np.zeros_like(yv)),</span>\n<span id="cb6-16"><a href="#cb6-16" aria-hidden="true" tabindex="-1"></a>            <span class="st">&quot;accuracy модели&quot;</span>: accuracy_score(yv, (p <span class="op">&gt;=</span> <span class="fl">0.5</span>).astype(<span class="bu">int</span>)),</span>\n<span id="cb6-17"><a href="#cb6-17" aria-hidden="true" tabindex="-1"></a>            <span class="st">&quot;ROC-AUC&quot;</span>: roc_auc_score(yv, p), <span class="st">&quot;PR-AUC&quot;</span>: average_precision_score(yv, p)}</span></code></pre></div>\n</div>\n<div id="cell013" class="cell code">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a>tab <span class="op">=</span> pd.DataFrame([evaluate_at_balance(f)</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a>                    <span class="cf">for</span> f <span class="kw">in</span> [<span class="fl">0.5</span>, <span class="fl">0.35</span>, <span class="fl">0.2</span>, <span class="fl">0.1</span>, <span class="fl">0.05</span>, <span class="fl">0.03</span>]]).set_index(<span class="st">&quot;доля класса 1&quot;</span>)</span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a>display(tab.<span class="bu">round</span>(<span class="dv">3</span>))</span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a>fig, ax <span class="op">=</span> plt.subplots()</span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> col <span class="kw">in</span> tab.columns:</span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a>    ax.plot(tab.index, tab[col], <span class="st">&quot;o-&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span>col)</span>\n<span id="cb7-8"><a href="#cb7-8" aria-hidden="true" tabindex="-1"></a>ax.invert_xaxis()<span class="op">;</span> ax.set_xlabel(<span class="st">&quot;доля класса 1&quot;</span>)<span class="op">;</span> ax.set_ylabel(<span class="st">&quot;значение метрики&quot;</span>)</span>\n<span id="cb7-9"><a href="#cb7-9" aria-hidden="true" tabindex="-1"></a>ax.set_title(<span class="st">&quot;Что происходит с метриками при росте дисбаланса&quot;</span>)<span class="op">;</span> ax.legend(fontsize<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb7-10"><a href="#cb7-10" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell014" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какая метрика перестаёт различать модель и\nконстанту? Чем PR-AUC отличается от ROC-AUC и какую вы возьмёте для\nпоиска редкого события (1 % положительных)?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell015" class="cell markdown">\n<h3 id="задание-31-порог--это-решение-а-не-константа">Задание 3.1. Порог\n— это решение, а не константа</h3>\n<p>Порог 0.5 ниоткуда не следует. Постройте precision, recall и\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>F</mi><mn>1</mn></msub><annotation encoding="application/x-tex">F_1</annotation></semantics></math>\nкак функции порога и найдите порог, максимизирующий\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>F</mi><mn>1</mn></msub><annotation encoding="application/x-tex">F_1</annotation></semantics></math>.</p>\n</div>\n<div id="cell016" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a>X, y <span class="op">=</span> make_classification(n_samples<span class="op">=</span><span class="dv">4000</span>, n_features<span class="op">=</span><span class="dv">20</span>, n_informative<span class="op">=</span><span class="dv">5</span>,</span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a>                          class_sep<span class="op">=</span><span class="fl">0.9</span>, flip_y<span class="op">=</span><span class="fl">0.02</span>, weights<span class="op">=</span>[<span class="fl">0.9</span>, <span class="fl">0.1</span>],</span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a>                          random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a>Xa, Xv, ya, yv <span class="op">=</span> train_test_split(X, y, test_size<span class="op">=</span><span class="fl">0.3</span>, stratify<span class="op">=</span>y, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a>s <span class="op">=</span> StandardScaler().fit(Xa)</span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a>scores <span class="op">=</span> LogisticRegression(max_iter<span class="op">=</span><span class="dv">5000</span>).fit(s.transform(Xa), ya).predict_proba(</span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a>    s.transform(Xv))[:, <span class="dv">1</span>]</span>\n<span id="cb8-10"><a href="#cb8-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-11"><a href="#cb8-11" aria-hidden="true" tabindex="-1"></a>ts <span class="op">=</span> np.linspace(<span class="fl">0.02</span>, <span class="fl">0.98</span>, <span class="dv">200</span>)</span>\n<span id="cb8-12"><a href="#cb8-12" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co"> (3-4 строки): посчитайте precision, recall и F1 для каждого порога,</span></span>\n<span id="cb8-13"><a href="#cb8-13" aria-hidden="true" tabindex="-1"></a><span class="co">#                    найдите порог с максимальным F1 и сравните с порогом 0.5.</span></span></code></pre></div>\n</div>\n<div id="cell017" class="cell code">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> precision_recall_curve, roc_curve</span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a>fpr, tpr, _ <span class="op">=</span> roc_curve(yv, scores)</span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a>prec, rec, _ <span class="op">=</span> precision_recall_curve(yv, scores)</span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a>fig, axes <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">3</span>, figsize<span class="op">=</span>(<span class="dv">15</span>, <span class="dv">4</span>))</span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>].plot(fpr, tpr, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="ss">f&quot;AUC = </span><span class="sc">{</span>roc_auc_score(yv, scores)<span class="sc">:.3f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb9-8"><a href="#cb9-8" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>].plot([<span class="dv">0</span>, <span class="dv">1</span>], [<span class="dv">0</span>, <span class="dv">1</span>], <span class="st">&quot;k--&quot;</span>, lw<span class="op">=</span><span class="dv">1</span>, label<span class="op">=</span><span class="st">&quot;случайный ответ&quot;</span>)</span>\n<span id="cb9-9"><a href="#cb9-9" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>].set_xlabel(<span class="st">&quot;FPR&quot;</span>)<span class="op">;</span> axes[<span class="dv">0</span>].set_ylabel(<span class="st">&quot;TPR&quot;</span>)<span class="op">;</span> axes[<span class="dv">0</span>].set_title(<span class="st">&quot;ROC&quot;</span>)</span>\n<span id="cb9-10"><a href="#cb9-10" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>].legend()</span>\n<span id="cb9-11"><a href="#cb9-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-12"><a href="#cb9-12" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">1</span>].plot(rec, prec, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="ss">f&quot;AP = </span><span class="sc">{</span>average_precision_score(yv, scores)<span class="sc">:.3f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb9-13"><a href="#cb9-13" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">1</span>].axhline(yv.mean(), ls<span class="op">=</span><span class="st">&quot;--&quot;</span>, color<span class="op">=</span><span class="st">&quot;black&quot;</span>, label<span class="op">=</span><span class="ss">f&quot;доля класса 1 = </span><span class="sc">{</span>yv<span class="sc">.</span>mean()<span class="sc">:.2f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb9-14"><a href="#cb9-14" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">1</span>].set_xlabel(<span class="st">&quot;recall&quot;</span>)<span class="op">;</span> axes[<span class="dv">1</span>].set_ylabel(<span class="st">&quot;precision&quot;</span>)<span class="op">;</span> axes[<span class="dv">1</span>].set_title(<span class="st">&quot;PR&quot;</span>)</span>\n<span id="cb9-15"><a href="#cb9-15" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">1</span>].legend()</span>\n<span id="cb9-16"><a href="#cb9-16" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-17"><a href="#cb9-17" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">2</span>].plot(ts, P, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;precision&quot;</span>)<span class="op">;</span> axes[<span class="dv">2</span>].plot(ts, R, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;recall&quot;</span>)</span>\n<span id="cb9-18"><a href="#cb9-18" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">2</span>].plot(ts, F1, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;$F_1$&quot;</span>)</span>\n<span id="cb9-19"><a href="#cb9-19" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">2</span>].axvline(t_best, ls<span class="op">=</span><span class="st">&quot;--&quot;</span>, color<span class="op">=</span><span class="st">&quot;black&quot;</span>, label<span class="op">=</span><span class="ss">f&quot;$t^* = </span><span class="sc">{</span>t_best<span class="sc">:.2f}</span><span class="ss">$&quot;</span>)</span>\n<span id="cb9-20"><a href="#cb9-20" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">2</span>].set_xlabel(<span class="st">&quot;порог&quot;</span>)<span class="op">;</span> axes[<span class="dv">2</span>].set_title(<span class="st">&quot;Метрики против порога&quot;</span>)<span class="op">;</span> axes[<span class="dv">2</span>].legend(fontsize<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb9-21"><a href="#cb9-21" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell018" class="cell markdown">\n<hr />\n<h1 id="часть-4-svm-решение-зависит-только-от-опорных-векторов">Часть 4.\nSVM: решение зависит только от опорных векторов</h1>\n<p>Прямая задача (опр. 3.9):\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi>min</mi><mo>⁡</mo></mrow><mfrac><mn>1</mn><mn>2</mn></mfrac><mo stretchy="false" form="postfix">∥</mo><mi>w</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\min\\frac12\\|w\\|^2</annotation></semantics></math>\nпри\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">(</mo><msup><mi>w</mi><mi>𝖳</mi></msup><msub><mi>x</mi><mi>i</mi></msub><mo>+</mo><mi>b</mi><mo stretchy="false" form="postfix">)</mo><mo>≥</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">y_i(w^{\\mathsf T}x_i+b)\\ge1</annotation></semantics></math>.\nВ двойственной задаче (теорема 3.11) появляются множители\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>α</mi><mi>i</mi></msub><annotation encoding="application/x-tex">\\alpha_i</annotation></semantics></math>,\nи</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>w</mi><mo>*</mo></msup><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><msubsup><mi>α</mi><mi>i</mi><mo>*</mo></msubsup><msub><mi>y</mi><mi>i</mi></msub><msub><mi>x</mi><mi>i</mi></msub><mi>.</mi></mrow><annotation encoding="application/x-tex">\nw^* = \\sum_i \\alpha_i^* y_i x_i .\n</annotation></semantics></math></p>\n<p>Объекты с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msubsup><mi>α</mi><mi>i</mi><mo>*</mo></msubsup><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\alpha_i^*&gt;0</annotation></semantics></math>\n— <strong>опорные векторы</strong>; по условию дополняющей нежёсткости\nони лежат ровно на границе полосы. Все остальные в сумму не входят\nвовсе. Проверим это буквально: удалим их.</p>\n</div>\n<div id="cell019" class="cell code">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a>Xb, yb <span class="op">=</span> make_blobs(n_samples<span class="op">=</span><span class="dv">60</span>, centers<span class="op">=</span><span class="dv">2</span>, cluster_std<span class="op">=</span><span class="fl">1.0</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a>yb <span class="op">=</span> np.where(yb <span class="op">==</span> <span class="dv">0</span>, <span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>)</span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a>Xb <span class="op">=</span> StandardScaler().fit_transform(Xb) <span class="op">*</span> <span class="fl">1.2</span></span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-5"><a href="#cb10-5" aria-hidden="true" tabindex="-1"></a>clf <span class="op">=</span> SVC(kernel<span class="op">=</span><span class="st">&quot;linear&quot;</span>, C<span class="op">=</span><span class="fl">1e6</span>).fit(Xb, yb)          <span class="co"># C огромно =&gt; жёсткий зазор</span></span>\n<span id="cb10-6"><a href="#cb10-6" aria-hidden="true" tabindex="-1"></a>sv <span class="op">=</span> clf.support_</span>\n<span id="cb10-7"><a href="#cb10-7" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;объектов </span><span class="sc">{</span><span class="bu">len</span>(yb)<span class="sc">}</span><span class="ss">, опорных векторов </span><span class="sc">{</span><span class="bu">len</span>(sv)<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb10-8"><a href="#cb10-8" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;w = </span><span class="sc">{</span>np<span class="sc">.</span><span class="bu">round</span>(clf.coef_[<span class="dv">0</span>], <span class="dv">5</span>)<span class="sc">}</span><span class="ss">, b = </span><span class="sc">{</span>clf<span class="sc">.</span>intercept_[<span class="dv">0</span>]<span class="sc">:.5f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb10-9"><a href="#cb10-9" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;ширина полосы 2/||w|| = </span><span class="sc">{</span><span class="dv">2</span> <span class="op">/</span> np<span class="sc">.</span>linalg<span class="sc">.</span>norm(clf.coef_[<span class="dv">0</span>])<span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell020" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb11"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb11-1"><a href="#cb11-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb11-2"><a href="#cb11-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-3"><a href="#cb11-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co"> (2-3 строки): обучите SVC(kernel=&quot;linear&quot;, C=1e6) ТОЛЬКО на опорных</span></span>\n<span id="cb11-4"><a href="#cb11-4" aria-hidden="true" tabindex="-1"></a><span class="co">#   векторах Xb[sv], yb[sv] и сравните полученные w и b с исходными.</span></span></code></pre></div>\n</div>\n<div id="cell021" class="cell code">\n<div class="sourceCode" id="cb12"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb12-1"><a href="#cb12-1" aria-hidden="true" tabindex="-1"></a>fig, ax <span class="op">=</span> plt.subplots(figsize<span class="op">=</span>(<span class="dv">6</span>, <span class="dv">5</span>))</span>\n<span id="cb12-2"><a href="#cb12-2" aria-hidden="true" tabindex="-1"></a>ax.scatter(<span class="op">*</span>Xb[yb <span class="op">==</span> <span class="dv">1</span>].T, s<span class="op">=</span><span class="dv">35</span>, marker<span class="op">=</span><span class="st">&quot;o&quot;</span>, label<span class="op">=</span><span class="st">&quot;$y = +1$&quot;</span>)</span>\n<span id="cb12-3"><a href="#cb12-3" aria-hidden="true" tabindex="-1"></a>ax.scatter(<span class="op">*</span>Xb[yb <span class="op">==</span> <span class="op">-</span><span class="dv">1</span>].T, s<span class="op">=</span><span class="dv">35</span>, marker<span class="op">=</span><span class="st">&quot;s&quot;</span>, label<span class="op">=</span><span class="st">&quot;$y = -1$&quot;</span>)</span>\n<span id="cb12-4"><a href="#cb12-4" aria-hidden="true" tabindex="-1"></a>ax.scatter(<span class="op">*</span>Xb[sv].T, s<span class="op">=</span><span class="dv">180</span>, facecolors<span class="op">=</span><span class="st">&quot;none&quot;</span>, edgecolors<span class="op">=</span><span class="st">&quot;red&quot;</span>, lw<span class="op">=</span><span class="fl">1.6</span>,</span>\n<span id="cb12-5"><a href="#cb12-5" aria-hidden="true" tabindex="-1"></a>           label<span class="op">=</span><span class="ss">f&quot;опорные векторы (</span><span class="sc">{</span><span class="bu">len</span>(sv)<span class="sc">}</span><span class="ss">)&quot;</span>)</span>\n<span id="cb12-6"><a href="#cb12-6" aria-hidden="true" tabindex="-1"></a>gx <span class="op">=</span> np.linspace(Xb[:, <span class="dv">0</span>].<span class="bu">min</span>() <span class="op">-</span> <span class="fl">0.5</span>, Xb[:, <span class="dv">0</span>].<span class="bu">max</span>() <span class="op">+</span> <span class="fl">0.5</span>, <span class="dv">200</span>)</span>\n<span id="cb12-7"><a href="#cb12-7" aria-hidden="true" tabindex="-1"></a>w, b <span class="op">=</span> clf.coef_[<span class="dv">0</span>], clf.intercept_[<span class="dv">0</span>]</span>\n<span id="cb12-8"><a href="#cb12-8" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> level, style <span class="kw">in</span> [(<span class="dv">0</span>, <span class="st">&quot;-&quot;</span>), (<span class="dv">1</span>, <span class="st">&quot;--&quot;</span>), (<span class="op">-</span><span class="dv">1</span>, <span class="st">&quot;--&quot;</span>)]:</span>\n<span id="cb12-9"><a href="#cb12-9" aria-hidden="true" tabindex="-1"></a>    ax.plot(gx, <span class="op">-</span>(w[<span class="dv">0</span>] <span class="op">*</span> gx <span class="op">+</span> b <span class="op">-</span> level) <span class="op">/</span> w[<span class="dv">1</span>], style, color<span class="op">=</span><span class="st">&quot;black&quot;</span>, lw<span class="op">=</span><span class="fl">1.5</span>)</span>\n<span id="cb12-10"><a href="#cb12-10" aria-hidden="true" tabindex="-1"></a>ax.set_ylim(Xb[:, <span class="dv">1</span>].<span class="bu">min</span>() <span class="op">-</span> <span class="fl">0.7</span>, Xb[:, <span class="dv">1</span>].<span class="bu">max</span>() <span class="op">+</span> <span class="fl">0.7</span>)</span>\n<span id="cb12-11"><a href="#cb12-11" aria-hidden="true" tabindex="-1"></a>ax.set_xlabel(<span class="st">&quot;$x_1$&quot;</span>)<span class="op">;</span> ax.set_ylabel(<span class="st">&quot;$x_2$&quot;</span>)<span class="op">;</span> ax.legend(fontsize<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb12-12"><a href="#cb12-12" aria-hidden="true" tabindex="-1"></a>ax.set_title(<span class="st">&quot;Разделяющая полоса и опорные векторы&quot;</span>)</span>\n<span id="cb12-13"><a href="#cb12-13" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell022" class="cell code">\n<div class="sourceCode" id="cb13"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb13-1"><a href="#cb13-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Мягкий зазор (опр. 3.14): параметр C -- цена нарушения отступа</span></span>\n<span id="cb13-2"><a href="#cb13-2" aria-hidden="true" tabindex="-1"></a>Xm, ym <span class="op">=</span> make_moons(n_samples<span class="op">=</span><span class="dv">200</span>, noise<span class="op">=</span><span class="fl">0.28</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb13-3"><a href="#cb13-3" aria-hidden="true" tabindex="-1"></a>ym <span class="op">=</span> np.where(ym <span class="op">==</span> <span class="dv">0</span>, <span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>)</span>\n<span id="cb13-4"><a href="#cb13-4" aria-hidden="true" tabindex="-1"></a>Xm <span class="op">=</span> StandardScaler().fit_transform(Xm)</span>\n<span id="cb13-5"><a href="#cb13-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-6"><a href="#cb13-6" aria-hidden="true" tabindex="-1"></a>rows <span class="op">=</span> []</span>\n<span id="cb13-7"><a href="#cb13-7" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> C <span class="kw">in</span> [<span class="fl">0.01</span>, <span class="fl">0.1</span>, <span class="fl">1.0</span>, <span class="fl">100.0</span>]:</span>\n<span id="cb13-8"><a href="#cb13-8" aria-hidden="true" tabindex="-1"></a>    m <span class="op">=</span> SVC(kernel<span class="op">=</span><span class="st">&quot;linear&quot;</span>, C<span class="op">=</span>C).fit(Xm, ym)</span>\n<span id="cb13-9"><a href="#cb13-9" aria-hidden="true" tabindex="-1"></a>    rows.append({<span class="st">&quot;C&quot;</span>: C, <span class="st">&quot;опорных векторов&quot;</span>: <span class="bu">len</span>(m.support_),</span>\n<span id="cb13-10"><a href="#cb13-10" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;ширина полосы 2/||w||&quot;</span>: <span class="dv">2</span> <span class="op">/</span> np.linalg.norm(m.coef_[<span class="dv">0</span>])})</span>\n<span id="cb13-11"><a href="#cb13-11" aria-hidden="true" tabindex="-1"></a>display(pd.DataFrame(rows).set_index(<span class="st">&quot;C&quot;</span>).<span class="bu">round</span>(<span class="dv">4</span>))</span></code></pre></div>\n</div>\n<div id="cell023" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Изменилось ли решение после удаления\nнеопорных объектов? Как число опорных векторов зависит от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>\nи какому пределу отвечает\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi><mo>→</mo><mi>∞</mi></mrow><annotation encoding="application/x-tex">C\\to\\infty</annotation></semantics></math>?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell024" class="cell markdown">\n<hr />\n<h1 id="часть-5-ядра">Часть 5. Ядра</h1>\n<p>Определение 3.17:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><msup><mi>x</mi><mo>′</mo></msup><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="prefix">⟨</mo><mi>φ</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>,</mo><mi>φ</mi><mo stretchy="false" form="prefix">(</mo><msup><mi>x</mi><mo>′</mo></msup><mo stretchy="false" form="postfix">)</mo><mo stretchy="false" form="postfix">⟩</mo></mrow><annotation encoding="application/x-tex">K(x,x&#39;) = \\langle\\varphi(x),\\varphi(x&#39;)\\rangle</annotation></semantics></math>\nдля некоторого отображения\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>φ</mi><annotation encoding="application/x-tex">\\varphi</annotation></semantics></math>.\nКритерий Мерсера:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>\n— ядро тогда и только тогда, когда матрица Грама\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mi>K</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>,</mo><msub><mi>x</mi><mi>j</mi></msub><mo stretchy="false" form="postfix">)</mo><mo stretchy="false" form="postfix">∥</mo></mrow><annotation encoding="application/x-tex">\\|K(x_i,x_j)\\|</annotation></semantics></math>\nсимметрична и неотрицательно определена.</p>\n<p>Проверить это можно прямо: посчитать собственные числа матрицы\nГрама.</p>\n</div>\n<div id="cell025" class="cell code">\n<div class="sourceCode" id="cb14"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb14-1"><a href="#cb14-1" aria-hidden="true" tabindex="-1"></a>pts <span class="op">=</span> rng.normal(size<span class="op">=</span>(<span class="dv">40</span>, <span class="dv">2</span>))</span>\n<span id="cb14-2"><a href="#cb14-2" aria-hidden="true" tabindex="-1"></a>d2 <span class="op">=</span> np.<span class="bu">sum</span>(pts <span class="op">**</span> <span class="dv">2</span>, <span class="dv">1</span>)[:, <span class="va">None</span>] <span class="op">-</span> <span class="dv">2</span> <span class="op">*</span> pts <span class="op">@</span> pts.T <span class="op">+</span> np.<span class="bu">sum</span>(pts <span class="op">**</span> <span class="dv">2</span>, <span class="dv">1</span>)[<span class="va">None</span>, :]</span>\n<span id="cb14-3"><a href="#cb14-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-4"><a href="#cb14-4" aria-hidden="true" tabindex="-1"></a>candidates <span class="op">=</span> {</span>\n<span id="cb14-5"><a href="#cb14-5" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;линейное  x^T x&#39;&quot;</span>: pts <span class="op">@</span> pts.T,</span>\n<span id="cb14-6"><a href="#cb14-6" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;полиномиальное (x^T x&#39; + 1)^3&quot;</span>: (pts <span class="op">@</span> pts.T <span class="op">+</span> <span class="dv">1</span>) <span class="op">**</span> <span class="dv">3</span>,</span>\n<span id="cb14-7"><a href="#cb14-7" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;RBF exp(-||x-x&#39;||^2)&quot;</span>: np.exp(<span class="op">-</span>np.maximum(d2, <span class="dv">0</span>)),</span>\n<span id="cb14-8"><a href="#cb14-8" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;сигмоидное tanh(0.1 x^T x&#39;)&quot;</span>: np.tanh(<span class="fl">0.1</span> <span class="op">*</span> pts <span class="op">@</span> pts.T),</span>\n<span id="cb14-9"><a href="#cb14-9" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;НЕ ядро: ||x - x&#39;||&quot;</span>: np.sqrt(np.maximum(d2, <span class="dv">0</span>)),</span>\n<span id="cb14-10"><a href="#cb14-10" aria-hidden="true" tabindex="-1"></a>}</span>\n<span id="cb14-11"><a href="#cb14-11" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> name, G <span class="kw">in</span> candidates.items():</span>\n<span id="cb14-12"><a href="#cb14-12" aria-hidden="true" tabindex="-1"></a>    lam_min <span class="op">=</span> np.linalg.eigvalsh((G <span class="op">+</span> G.T) <span class="op">/</span> <span class="dv">2</span>).<span class="bu">min</span>()</span>\n<span id="cb14-13"><a href="#cb14-13" aria-hidden="true" tabindex="-1"></a>    <span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>name<span class="sc">:32s}</span><span class="ss"> min lambda = </span><span class="sc">{</span>lam_min<span class="sc">:+9.4f}</span><span class="ss">  -&gt;  &quot;</span></span>\n<span id="cb14-14"><a href="#cb14-14" aria-hidden="true" tabindex="-1"></a>          <span class="ss">f&quot;</span><span class="sc">{</span><span class="st">&#39;ядро&#39;</span> <span class="cf">if</span> lam_min <span class="op">&gt;</span> <span class="op">-</span><span class="fl">1e-8</span> <span class="cf">else</span> <span class="st">&#39;НЕ ядро&#39;</span><span class="sc">}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell026" class="cell code">\n<div class="sourceCode" id="cb15"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb15-1"><a href="#cb15-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Ядровой переход: одна и та же двойственная задача, разные K</span></span>\n<span id="cb15-2"><a href="#cb15-2" aria-hidden="true" tabindex="-1"></a>Xc, yc <span class="op">=</span> make_circles(n_samples<span class="op">=</span><span class="dv">200</span>, noise<span class="op">=</span><span class="fl">0.12</span>, factor<span class="op">=</span><span class="fl">0.45</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb15-3"><a href="#cb15-3" aria-hidden="true" tabindex="-1"></a>Xc <span class="op">=</span> StandardScaler().fit_transform(Xc)</span>\n<span id="cb15-4"><a href="#cb15-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-5"><a href="#cb15-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-6"><a href="#cb15-6" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> plot_boundary(ax, model, X, y, title):</span>\n<span id="cb15-7"><a href="#cb15-7" aria-hidden="true" tabindex="-1"></a>    g1, g2 <span class="op">=</span> np.meshgrid(np.linspace(X[:, <span class="dv">0</span>].<span class="bu">min</span>() <span class="op">-</span> <span class="fl">.5</span>, X[:, <span class="dv">0</span>].<span class="bu">max</span>() <span class="op">+</span> <span class="fl">.5</span>, <span class="dv">200</span>),</span>\n<span id="cb15-8"><a href="#cb15-8" aria-hidden="true" tabindex="-1"></a>                         np.linspace(X[:, <span class="dv">1</span>].<span class="bu">min</span>() <span class="op">-</span> <span class="fl">.5</span>, X[:, <span class="dv">1</span>].<span class="bu">max</span>() <span class="op">+</span> <span class="fl">.5</span>, <span class="dv">200</span>))</span>\n<span id="cb15-9"><a href="#cb15-9" aria-hidden="true" tabindex="-1"></a>    Z <span class="op">=</span> model.decision_function(np.c_[g1.ravel(), g2.ravel()]).reshape(g1.shape)</span>\n<span id="cb15-10"><a href="#cb15-10" aria-hidden="true" tabindex="-1"></a>    ax.contourf(g1, g2, Z, levels<span class="op">=</span>[<span class="op">-</span><span class="fl">1e9</span>, <span class="dv">0</span>, <span class="fl">1e9</span>], colors<span class="op">=</span>[<span class="st">&quot;#cfe8e4&quot;</span>, <span class="st">&quot;#f6ddc4&quot;</span>], alpha<span class="op">=</span><span class="fl">.8</span>)</span>\n<span id="cb15-11"><a href="#cb15-11" aria-hidden="true" tabindex="-1"></a>    ax.contour(g1, g2, Z, levels<span class="op">=</span>[<span class="dv">0</span>], colors<span class="op">=</span><span class="st">&quot;black&quot;</span>, linewidths<span class="op">=</span><span class="fl">1.8</span>)</span>\n<span id="cb15-12"><a href="#cb15-12" aria-hidden="true" tabindex="-1"></a>    ax.scatter(<span class="op">*</span>X[y <span class="op">==</span> <span class="dv">0</span>].T, s<span class="op">=</span><span class="dv">14</span>, marker<span class="op">=</span><span class="st">&quot;o&quot;</span>)<span class="op">;</span> ax.scatter(<span class="op">*</span>X[y <span class="op">==</span> <span class="dv">1</span>].T, s<span class="op">=</span><span class="dv">14</span>, marker<span class="op">=</span><span class="st">&quot;s&quot;</span>)</span>\n<span id="cb15-13"><a href="#cb15-13" aria-hidden="true" tabindex="-1"></a>    ax.set_title(title, fontsize<span class="op">=</span><span class="dv">9</span>)<span class="op">;</span> ax.set_xticks([])<span class="op">;</span> ax.set_yticks([])</span></code></pre></div>\n</div>\n<div id="cell027" class="cell code">\n<div class="sourceCode" id="cb16"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb16-1"><a href="#cb16-1" aria-hidden="true" tabindex="-1"></a>fig, axes <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">4</span>, figsize<span class="op">=</span>(<span class="dv">16</span>, <span class="dv">4</span>))</span>\n<span id="cb16-2"><a href="#cb16-2" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> ax, (name, kw) <span class="kw">in</span> <span class="bu">zip</span>(axes, [(<span class="st">&quot;линейное&quot;</span>, <span class="bu">dict</span>(kernel<span class="op">=</span><span class="st">&quot;linear&quot;</span>)),</span>\n<span id="cb16-3"><a href="#cb16-3" aria-hidden="true" tabindex="-1"></a>                                 (<span class="st">&quot;полиномиальное d=2&quot;</span>, <span class="bu">dict</span>(kernel<span class="op">=</span><span class="st">&quot;poly&quot;</span>, degree<span class="op">=</span><span class="dv">2</span>)),</span>\n<span id="cb16-4"><a href="#cb16-4" aria-hidden="true" tabindex="-1"></a>                                 (<span class="st">&quot;RBF, gamma=1&quot;</span>, <span class="bu">dict</span>(kernel<span class="op">=</span><span class="st">&quot;rbf&quot;</span>, gamma<span class="op">=</span><span class="fl">1.0</span>)),</span>\n<span id="cb16-5"><a href="#cb16-5" aria-hidden="true" tabindex="-1"></a>                                 (<span class="st">&quot;RBF, gamma=100&quot;</span>, <span class="bu">dict</span>(kernel<span class="op">=</span><span class="st">&quot;rbf&quot;</span>, gamma<span class="op">=</span><span class="fl">100.0</span>))]):</span>\n<span id="cb16-6"><a href="#cb16-6" aria-hidden="true" tabindex="-1"></a>    m <span class="op">=</span> SVC(C<span class="op">=</span><span class="fl">1.0</span>, <span class="op">**</span>kw).fit(Xc, yc)</span>\n<span id="cb16-7"><a href="#cb16-7" aria-hidden="true" tabindex="-1"></a>    plot_boundary(ax, m, Xc, yc,</span>\n<span id="cb16-8"><a href="#cb16-8" aria-hidden="true" tabindex="-1"></a>                  <span class="ss">f&quot;</span><span class="sc">{</span>name<span class="sc">}</span><span class="ch">\\n</span><span class="ss">точность </span><span class="sc">{</span>m<span class="sc">.</span>score(Xc, yc)<span class="sc">:.2f}</span><span class="ss">, опорных </span><span class="sc">{</span><span class="bu">len</span>(m.support_)<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb16-9"><a href="#cb16-9" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell028" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какие функции не прошли критерий Мерсера? Что\nпроисходит с границей при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>γ</mi><mo>→</mo><mi>∞</mi></mrow><annotation encoding="application/x-tex">\\gamma\\to\\infty</annotation></semantics></math>\nи почему это переобучение?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell029" class="cell markdown">\n<hr />\n<h1 id="часть-6-своя-выборка">Часть 6. Своя выборка</h1>\n</div>\n<div id="cell030" class="cell code">\n<div class="sourceCode" id="cb17"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb17-1"><a href="#cb17-1" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_personal(variant)</span>\n<span id="cb17-2"><a href="#cb17-2" aria-hidden="true" tabindex="-1"></a>Xtr, Xte, ytr, yte <span class="op">=</span> data[<span class="st">&quot;X_train&quot;</span>], data[<span class="st">&quot;X_test&quot;</span>], data[<span class="st">&quot;y_train&quot;</span>], data[<span class="st">&quot;y_test&quot;</span>]</span>\n<span id="cb17-3"><a href="#cb17-3" aria-hidden="true" tabindex="-1"></a><span class="cf">if</span> data[<span class="st">&quot;task&quot;</span>] <span class="op">==</span> <span class="st">&quot;regression&quot;</span>:</span>\n<span id="cb17-4"><a href="#cb17-4" aria-hidden="true" tabindex="-1"></a>    thr <span class="op">=</span> np.median(ytr)</span>\n<span id="cb17-5"><a href="#cb17-5" aria-hidden="true" tabindex="-1"></a>    ytr, yte <span class="op">=</span> (ytr <span class="op">&gt;</span> thr).astype(<span class="bu">int</span>), (yte <span class="op">&gt;</span> thr).astype(<span class="bu">int</span>)</span>\n<span id="cb17-6"><a href="#cb17-6" aria-hidden="true" tabindex="-1"></a>    <span class="bu">print</span>(<span class="ss">f&quot;регрессионный вариант бинаризован по медиане обучающей выборки&quot;</span>)</span>\n<span id="cb17-7"><a href="#cb17-7" aria-hidden="true" tabindex="-1"></a>ytr, yte <span class="op">=</span> ytr.astype(<span class="bu">int</span>), yte.astype(<span class="bu">int</span>)</span>\n<span id="cb17-8"><a href="#cb17-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb17-9"><a href="#cb17-9" aria-hidden="true" tabindex="-1"></a>rows <span class="op">=</span> []</span>\n<span id="cb17-10"><a href="#cb17-10" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> name, m <span class="kw">in</span> [(<span class="st">&quot;логистическая регрессия&quot;</span>, LogisticRegression(C<span class="op">=</span><span class="fl">1.0</span>, max_iter<span class="op">=</span><span class="dv">5000</span>)),</span>\n<span id="cb17-11"><a href="#cb17-11" aria-hidden="true" tabindex="-1"></a>                (<span class="st">&quot;SVM (линейное ядро)&quot;</span>, SVC(kernel<span class="op">=</span><span class="st">&quot;linear&quot;</span>, C<span class="op">=</span><span class="fl">1.0</span>)),</span>\n<span id="cb17-12"><a href="#cb17-12" aria-hidden="true" tabindex="-1"></a>                (<span class="st">&quot;SVM (RBF)&quot;</span>, SVC(kernel<span class="op">=</span><span class="st">&quot;rbf&quot;</span>, C<span class="op">=</span><span class="fl">1.0</span>, gamma<span class="op">=</span><span class="st">&quot;scale&quot;</span>))]:</span>\n<span id="cb17-13"><a href="#cb17-13" aria-hidden="true" tabindex="-1"></a>    m.fit(Xtr, ytr)</span>\n<span id="cb17-14"><a href="#cb17-14" aria-hidden="true" tabindex="-1"></a>    s <span class="op">=</span> m.decision_function(Xte)</span>\n<span id="cb17-15"><a href="#cb17-15" aria-hidden="true" tabindex="-1"></a>    rows.append({<span class="st">&quot;модель&quot;</span>: name, <span class="st">&quot;ROC-AUC&quot;</span>: roc_auc_score(yte, s),</span>\n<span id="cb17-16"><a href="#cb17-16" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;accuracy&quot;</span>: accuracy_score(yte, m.predict(Xte)),</span>\n<span id="cb17-17"><a href="#cb17-17" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;опорных векторов&quot;</span>: <span class="bu">len</span>(m.support_) <span class="cf">if</span> <span class="bu">isinstance</span>(m, SVC) <span class="cf">else</span> <span class="st">&quot;-&quot;</span>})</span>\n<span id="cb17-18"><a href="#cb17-18" aria-hidden="true" tabindex="-1"></a>rows.append({<span class="st">&quot;модель&quot;</span>: <span class="st">&quot;константа&quot;</span>, <span class="st">&quot;ROC-AUC&quot;</span>: <span class="fl">0.5</span>,</span>\n<span id="cb17-19"><a href="#cb17-19" aria-hidden="true" tabindex="-1"></a>             <span class="st">&quot;accuracy&quot;</span>: <span class="bu">max</span>(yte.mean(), <span class="dv">1</span> <span class="op">-</span> yte.mean()), <span class="st">&quot;опорных векторов&quot;</span>: <span class="st">&quot;-&quot;</span>})</span>\n<span id="cb17-20"><a href="#cb17-20" aria-hidden="true" tabindex="-1"></a>display(pd.DataFrame(rows).set_index(<span class="st">&quot;модель&quot;</span>).<span class="bu">round</span>(<span class="dv">4</span>))</span></code></pre></div>\n</div>\n<div id="cell031" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какая модель победила? Сколько объектов\nоказалось опорными и о чём это говорит? Насколько корректно такое\nсравнение?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell032" class="cell markdown">\n<h2 id="итоги-занятия">Итоги занятия</h2>\n<p>Ответьте письменно на контрольные вопросы (по 2–4 предложения):</p>\n<ol>\n<li>Логистическая регрессия минимизирует\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mo>∑</mo><mi>i</mi></msub><mrow><mi>ln</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>+</mo><msup><mi>e</mi><mrow><mi>−</mi><msub><mi>M</mi><mi>i</mi></msub></mrow></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\sum_i\\ln(1+e^{-M_i})</annotation></semantics></math>,\nSVM —\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mn>1</mn><mn>2</mn></mfrac><mo stretchy="false" form="postfix">∥</mo><mi>w</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>+</mo><mi>C</mi><msub><mo>∑</mo><mi>i</mi></msub><mrow><mi>max</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo>−</mo><msub><mi>M</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\frac12\\|w\\|^2 + C\\sum_i\\max(0,1-M_i)</annotation></semantics></math>.\nНазовите два различия в поведении, следующих прямо из вида этих\nпотерь.</li>\n<li>Почему на линейно разделимой выборке у логистической регрессии без\nрегуляризации нет минимума, а у SVM с жёстким зазором — есть?</li>\n<li>У вас 1 000 000 объектов, из них 500 положительных. Модель даёт\naccuracy 0.9995 и ROC-AUC 0.97. Достаточно ли этого для внедрения?</li>\n<li>Что такое опорный вектор и почему классификатор не меняется при\nудалении неопорных объектов?</li>\n</ol>\n<hr />\n<p><strong>Дома:</strong> откройте <code>lab04_homework.ipynb</code> —\nтам три задачи: своя логистическая регрессия с методом Ньютона, своя\nROC-кривая и двойственная задача SVM.</p>\n</div>\n</body>\n</html>\n'}}]);